window.products.push({"id":1184373,"name":"Logisys SOHO CS2008XBK Black Top USB Tool Less ATX Mid Tower / Computer Case","category":"electronics","retail price":0.0,"sale price":null,"image":"https://m.media-amazon.com/images/I/31n+kPVS+tL._AC_.jpg","description":"Build your own high performance computer system with the IKONIK SOHO2 ATX Case! This 10-bay ATX case features four 5.25-inch external drive bays, one 3.5-inch external drive bay and five 3.5-inch internal drive bays! Its tool-free lock and release design makes drive installation a breeze! This well designed computer case even comes equipped with a 480-watt power supply! The CS2008BK comes with a TAC 2.0 side panel, supporting 120 mm and 140 mm fans on the side and top for maximum airflow potentional. For water-cooled systems, this case features rear water tube holes for setting up your external liquid cooling system (liquid cooling system not included). Located on top of the case are two USB 2.0 ports, one microphone in jack and one headphone out jack for hassle-free connectivity! All you need is to add the motherboard and the rest of the system! Order your IKONIK SOHO2 CS2008BK ATX Case today!","images":["https://m.media-amazon.com/images/I/31n+kPVS+tL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Logisys/Ikonik","source_asin":"B004DFO20C","category_path":"Electronics"},"sku":"BM-1184373","productType":"Electronics","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B004DFO20C","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"electronics-range.jsonl","source_asin":"B004DFO20C","price_pending":true,"merchant_ready":false});
